248	    /**
249	     * Tells whether or not there's at least one node from the sites tree in context.
250	     *
251	     * <p>The whole tree is traversed until is found one node in context.
252	     *
253	     * @param node the node to check, recursively
254	     * @return {@code true} if the context has at least one node from the sites tree in context,
255	     *     {@code false} otherwise
256	     */
257	    private boolean hasNodesInContext(SiteNode node) {
258	        @SuppressWarnings("unchecked")
259	        Enumeration<TreeNode> en = node.children();
260	        while (en.hasMoreElements()) {
261	            SiteNode sn = (SiteNode) en.nextElement();
262	            if (isInContext(sn)) {
263	                return true;
264	            }
265	            if (hasNodesInContext(sn)) {
266	                return true;
267	            }
268	        }
269	        return false;
270	    }
